def admit(active, waiting, budget, slots):
    if any(value > budget for value in waiting):
        raise ValueError("reservation exceeds total budget")
    admitted = []
    used = sum(active)
    used_slots = len(active)
    for i, value in enumerate(waiting):
        if used + value > budget or used_slots + len(admitted) + 1 > slots:
            return admitted, waiting[i:]
        admitted.append(value)
        used += value
    return admitted, []

